export default function build({holeScale=parameters.holeScale,pocketFloor=parameters.pocketFloor}={}){
 if(!Number.isFinite(holeScale)||holeScale<=0)throw Error('Hole scale must be positive');
 if(!Number.isFinite(pocketFloor)||pocketFloor<=0||pocketFloor>=stockFrame.depth)throw Error('Pocket floor must be between zero and stock thickness');
 const stock=buildPrismaticPart({...stockFrame,outline:perimeter,cutouts:[
  ...throughSlots,
  ...mountingHoles.flatMap(g=>g.centers.map(center=>[{kind:'circle',center,radius:g.diameter*holeScale/2}]))
 ]});
 const clearance=buildPrismaticPart({...recess,
  origin:stockFrame.origin.map((v,i)=>v+stockFrame.direction[i]*pocketFloor),
  depth:stockFrame.depth-pocketFloor+.00001
 });
 return unwrap(cut(stock,clearance));
}
